{
  "schema_version": 1,
  "skill_id": "product-context-brief",
  "stage": "planned",
  "cases": [
    {
      "id": "draft-with-evidence-gaps",
      "prompt": "请根据这些材料写一份可供产品与销售共用的简短产品背景。材料：LumenDesk 当前已上线 CSV 导入和重复记录提醒；团队计划下季度开发 SSO，但尚未承诺日期。一次为期 3 周的内部试点覆盖 8 个团队，其中 6 个团队报告每周约节省 20 分钟。定价尚未决定。客户原话 Q1：‘终于不用逐行找重复项了。’内部想法 I1：‘也许可以主打零配置迁移。’不要查外部资料，也不要保存文件。",
      "input": {
        "kind": "synthetic",
        "text": "合成产品、试点、路线图、客户引语和内部想法。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "将 CSV 导入和重复记录提醒表述为当前能力，并将 SSO 表述为计划而非已上线或已承诺",
        "保留试点的 3 周、8 个团队、其中 6 个团队及每周约 20 分钟的范围",
        "将 Q1 保留为有来源的客户原话，将 I1 标明为内部想法而非客户证据",
        "明确价格仍未知，并给出足以供产品与销售共用的紧凑背景"
      ],
      "must_avoid": [
        "把路线图写成已交付功能、承诺或销售事实",
        "编造客户引语、价格、竞品事实或更强的试点结论",
        "声称已经查阅外部资料、保存文件或自动写入工作区"
      ]
    },
    {
      "id": "separate-buying-roles",
      "prompt": "把以下访谈摘记整理成角色与需求摘要：客服助理每天实际使用工单表；运营负责人整理需求并向公司推荐工具；CFO 说‘如果提交预算申请，我可能会复核’，但尚未确认谁最终批准采购。当前替代方案是共享表格加邮件提醒。只根据这些材料，不要猜组织架构或竞品。",
      "input": {
        "kind": "synthetic",
        "text": "合成购买角色与当前替代方案访谈。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "区分客服助理是实际用户、运营负责人是推荐者或推动者",
        "把 CFO 仅表述为可能复核预算的人，并明确最终决策者或付款方尚未确认",
        "将共享表格加邮件提醒保留为当前替代方案"
      ],
      "must_avoid": [
        "仅凭 CFO 头衔或条件句断定其是最终决策者、付款方或采购批准人",
        "编造组织关系、预算权限、未给出的需求或竞品能力"
      ]
    },
    {
      "id": "update-bounded-context",
      "prompt": "下面是现有背景，请按更正 C1 只更新 Audience 和 Evidence，返回完整四节；Product 和 Voice 必须逐字不变。更正关系要保留，不要静默删除旧说法。\n\nProduct\nBeacon 把支持邮件整理成待办列表。\n\nAudience\n主要用户：支持经理。\n\nEvidence\nE1（4月访谈）：受访者被记录为支持经理，并说‘我每天先分拣邮箱。’\n\nVoice\n直接、克制，不使用‘革命性’。\n\nC1（5月更正）：E1 的受访者实际职位是支持协调员；引语内容不变。",
      "input": {
        "kind": "synthetic",
        "text": "合成既有四节背景及一条带日期的身份更正。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "Audience 更新为支持协调员",
        "Evidence 保留 E1 的历史说法、C1 的更正来源及引语内容不变",
        "返回完整四节且 Product 与 Voice 的正文逐字不变"
      ],
      "must_avoid": [
        "静默删除 E1 或把更正后的身份伪装成 E1 当时原始记录",
        "修改 Product 或 Voice 的正文",
        "因这次内容更正擅自引入或递增文档版本号"
      ]
    },
    {
      "id": "compact-sufficient-context",
      "prompt": "材料已经足够，只给恰好 4 个要点，不要提问：产品 PineQueue 为社区诊所整理候诊回电；实际用户是前台协调员；痛点是来电记录散落在便签和共享收件箱；当前功能会合并同一患者的重复回电请求；一轮 5 家诊所、2 周的试用中，4 家称遗漏回电变少，但没有统一计数。",
      "input": {
        "kind": "synthetic",
        "text": "合成且足够完整的紧凑产品背景。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "输出恰好 4 个要点",
        "覆盖产品及实际用户",
        "覆盖痛点及当前功能",
        "保留 5 家诊所、2 周、4 家的试用范围，并说明没有统一计数"
      ],
      "must_avoid": [
        "在材料充足时追加问题、长模板或营销活动方案",
        "把试用反馈外推成全部诊所的量化成效",
        "声称保存、发布或同步了背景"
      ]
    }
  ]
}

