packages.baseline_snapshot:
{
  "schema_version": 1,
  "skill_id": "article-visual-plan",
  "stage": "planned",
  "cases": [
    {
      "id": "choose-informative-positions",
      "prompt": "为这篇短文规划最多 2 张图，只给插入位置和画面简述，不写完整生成提示词：P1 介绍背景；P2 描述三步流程：收集请求→人工复核→发布；P3 是作者感想；P4 比较集中处理与逐条处理的优缺点；P5 总结。图必须帮助理解，不要为每段装饰。",
      "input": {
        "kind": "synthetic",
        "text": "合成的五段文章骨架。"
      },
      "expected_route": "article-visual-plan",
      "must_include": [
        "选择 P2 的三步流程作为有信息价值的插图位置，并保持流程顺序",
        "选择 P4 的集中处理与逐条处理比较作为另一插图位置，并体现双方优缺点",
        "每张图都给出明确位置和帮助理解的目的或画面关系",
        "总数不超过 2 张且只提供规划级简述"
      ],
      "must_avoid": [
        "为 P1、P3 或 P5 添加无信息价值的装饰图",
        "输出完整生成提示词、虚构文件名、嵌入图片或声称图片已生成"
      ]
    },
    {
      "id": "preserve-visual-uncertainty",
      "prompt": "给设计师规划 1 张 16:9 对比图。文章只有定性访谈：受访者常说方案 A ‘感觉更快’，但没有测量耗时，也没有证据说明 A 导致效率提升；方案 B 被描述为步骤更多。请让图可执行，同时保留这种不确定性。",
      "input": {
        "kind": "synthetic",
        "text": "合成的定性方案比较材料，没有量化数据或因果证据。"
      },
      "expected_route": "article-visual-plan",
      "must_include": [
        "规划恰好 1 张 16:9 对比图并给出可执行的布局或区域关系",
        "把 A 的更快表述为受访者感受，把 B 表述为步骤更多",
        "明确没有耗时测量，也不能用画面暗示 A 导致效率提升"
      ],
      "must_avoid": [
        "编造百分比、时间值、比例柱、精确坐标轴或样本规模",
        "添加因果箭头、胜负结论或其他超出材料的关系",
        "声称已经生成或保存图片"
      ]
    },
    {
      "id": "revise-one-visual",
      "prompt": "只修订 V2 的完整生成提示词，返回完整计划；V1 和 V3 必须逐字不变，ID 与共同风格保持不变，不要生成图片。更正：系统不会自动批准，而是把请求交给人工复核。\n\nV1 | 位置：开头后 | 共同风格：蓝灰扁平线稿 | 提示词：16:9，左侧用户提交请求，右侧队列接收；仅显示‘提交’与‘队列’。\nV2 | 位置：流程段后 | 共同风格：蓝灰扁平线稿 | 提示词：16:9，从‘队列’用箭头直达‘自动批准’，再到‘发布’。\nV3 | 位置：结尾前 | 共同风格：蓝灰扁平线稿 | 提示词：16:9，三个并列卡片标注‘可追踪’‘可回退’‘有记录’。",
      "input": {
        "kind": "synthetic",
        "text": "合成三图计划及只影响中间一图的流程更正。"
      },
      "expected_route": "article-visual-plan",
      "must_include": [
        "返回 V1、V2、V3 的完整计划且三个 ID 与共同风格不变",
        "V1 和 V3 的整行内容逐字不变",
        "仅把 V2 的错误自动批准关系改为队列交给人工复核，再衔接发布",
        "V2 仍是可用于生成的完整提示词，而不是只给修改说明"
      ],
      "must_avoid": [
        "修改 V1 或 V3 的文字、位置、标签、比例或风格",
        "保留或暗示自动批准",
        "生成图片、创建文件或声称已完成渲染"
      ]
    },
    {
      "id": "respect-explicit-diagram-brief",
      "prompt": "请给一张中文 16:9 流程图写完整生成提示词，只能使用这些节点和关系：起点‘收到申请’→判断‘资料齐全？’；否→‘补充资料’→回到‘资料齐全？’；是→‘人工复核’→判断‘通过？’；是→‘发布’；否→‘退回修改’。不要生成图片，不要加新节点，不要改成故事插画。",
      "input": {
        "kind": "synthetic",
        "text": "合成的显式流程图约束。"
      },
      "expected_route": "article-visual-plan",
      "must_include": [
        "输出一份中文 16:9 的完整生成提示词",
        "完整保留收到申请、资料齐全判断、补充资料回环、人工复核、通过判断、发布和退回修改",
        "明确两个判断节点的是与否分支及规定的箭头方向",
        "以流程图结构描述布局、节点、连线和必要的可读性要求"
      ],
      "must_avoid": [
        "增加未给出的节点、步骤、分支、数据或因果关系",
        "遗漏补充资料回环或任一是否分支",
        "改成故事场景、装饰插画，或声称图片已生成"
      ]
    }
  ]
}

